function convertOrRepopulateDiagnosticMessageChainArray<T extends DiagnosticMessageChain | ReusableDiagnosticMessageChain>(
    array: T[] | undefined,
    sourceFile: SourceFile | undefined,
    newProgram: Program,
    repopulateInfo: (chain: T) => RepopulateDiagnosticChainInfo | undefined,
): DiagnosticMessageChain[] | undefined;
function convertOrRepopulateDiagnosticMessageChainArray(
    array: (DiagnosticMessageChain | ReusableDiagnosticMessageChain)[] | undefined,
    sourceFile: SourceFile | undefined,
    newProgram: Program,
    repopulateInfo: (chain: DiagnosticMessageChain | ReusableDiagnosticMessageChain) => RepopulateDiagnosticChainInfo | undefined,
): DiagnosticMessageChain[] | undefined {
    if (array === undefined) return array;
    if (array.every(isFullChain)) {
        return sameMap<DiagnosticMessageChain>(array, chain => convertOrRepopulateDiagnosticMessageChain(chain, sourceFile, newProgram, repopulateInfo));
    }
    return array.map(chain => convertOrRepopulateDiagnosticMessageChain(chain, sourceFile, newProgram, repopulateInfo));

    function isFullChain(chain: DiagnosticMessageChain | ReusableDiagnosticMessageChain): chain is DiagnosticMessageChain {
        return "messageText" in chain && "category" in chain && "code" in chain
            && (chain.next === undefined || chain.next.every(isFullChain));
    }
}
